import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Calculate plane dimensions from atlas region aspect ratio
  const atlasRegion = config.atlasRegion || { width: 512, height: 320 };
  const aspectRatio = atlasRegion.width / atlasRegion.height;
  const planeHeight = 1.0;
  const planeWidth = planeHeight * aspectRatio;

  // Create sprite plane geometry
  const planeGeometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load ceramic grain texture and create TSL material
  const textureMap = ctx.textureLoader.load(config.assets.imageUrl);
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(textureMap);

  // Add plane mesh to group
  const planeMesh = new THREE.Mesh(planeGeometry, material);
  group.add(planeMesh);

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textObject = ctx.fontAtlas(config.textContent[0], {
      size: 0.34,
      color: 0x16161d,
    });
    if (textObject) {
      textObject.position.z = 0.01;
      group.add(textObject);
    }
  }

  // Setup resource cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // Apply cinematic primitives (if any)
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    }
  }

  return group;
}
